import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X, Home, User, Image, Star, Phone, Sparkles } from "lucide-react";

const navItems = [
  { label: "Home", href: "#top", icon: Home },
  { label: "About", href: "#about", icon: User },
  { label: "Collections", href: "#collections", icon: Image },
  { label: "Reviews", href: "#reviews", icon: Star },
  { label: "Contact", href: "#contact", icon: Phone },
];

// Expandable tab animation
const expandVariants = {
  collapsed: { width: 48 },
  expanded: { width: "auto" }
};

const textVariants = {
  hidden: { opacity: 0, width: 0, marginLeft: 0 },
  visible: { opacity: 1, width: "auto", marginLeft: 8, transition: { duration: 0.2 } }
};

const itemVariants = {
  collapsed: { justifyContent: "center" },
  expanded: { justifyContent: "flex-start" }
};

// Mobile menu animation variants
const mobileMenuVariants = {
  hidden: { opacity: 0, y: -20, scale: 0.95 },
  visible: { opacity: 1, y: 0, scale: 1, transition: { duration: 0.3, ease: "easeOut" } },
  exit: { opacity: 0, y: -20, scale: 0.95, transition: { duration: 0.2 } }
};

// Nav link hover animation
const navLinkVariants = {
  rest: { scale: 1 },
  hover: { scale: 1.05 }
};

export default function Navbar({ onOpenQuote }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  const [expandedItem, setExpandedItem] = useState(null);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <motion.header
      className="fixed top-0 inset-x-0 z-40 transition-all duration-500 py-3"
      style={{
        background: scrolled
          ? "rgba(253, 248, 237, 0.95)"
          : "rgba(255,255,255,0.85)",
        backdropFilter: "blur(20px)",
        WebkitBackdropFilter: "blur(20px)",
        borderBottom: `1px solid ${scrolled ? "rgba(212,175,55,0.3)" : "rgba(212,175,55,0.15)"}`,
        boxShadow: scrolled ? "0 4px 30px rgba(212,175,55,0.15)" : "none",
      }}
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      transition={{ duration: 0.6, ease: "easeOut" }}
    >
      {/* Glass Reflection Effect */}
      <div
        className="absolute inset-0 pointer-events-none overflow-hidden"
        style={{ borderRadius: 0 }}
      >
        <motion.div
          className="absolute top-0 left-0 w-full h-full"
          style={{
            background: "linear-gradient(180deg, rgba(255,255,255,0.4) 0%, transparent 50%)",
          }}
          animate={{
            opacity: scrolled ? 0.3 : 0.6,
          }}
          transition={{ duration: 0.3 }}
        />
      </div>

      <div className="relative flex items-center justify-between px-6 md:px-12 lg:px-24">
        {/* Logo */}
        <motion.a
          href="#top"
          className="flex items-center gap-3 z-10"
          whileHover={{ scale: 1.02 }}
          transition={{ type: "spring", stiffness: 400, damping: 25 }}
        >
          <span className="serif tracking-[0.2em] uppercase" style={{ fontSize: 22, color: "#d4af37", fontWeight: 500 }}>D Sajawat</span>
          <motion.span
            className="hidden md:inline-block w-12 h-px"
            style={{ background: "rgba(212,175,55,0.5)" }}
            initial={{ width: 0 }}
            animate={{ width: 48 }}
            transition={{ delay: 0.5, duration: 0.5 }}
          />
          <span className="hidden md:inline serif italic" style={{ color: "rgba(26,8,10,0.6)", fontSize: 16 }}>Premium Fabrics</span>
          <motion.span
            className="hidden lg:inline-flex items-center gap-1 px-3 py-1.5 rounded-full text-xs font-semibold"
            style={{
              background: "linear-gradient(135deg, #d4af37, #f4d77a)",
              color: "#1a080a",
              boxShadow: "0 2px 10px rgba(212,175,55,0.3)"
            }}
            whileHover={{ scale: 1.1, boxShadow: "0 4px 20px rgba(212,175,55,0.5)" }}
            transition={{ type: "spring", stiffness: 400, damping: 25 }}
          >
            <motion.span
              animate={{ rotate: [0, 360] }}
              transition={{ duration: 10, repeat: Infinity, ease: "linear" }}
            >
              ⭐
            </motion.span>
            Since 2012
          </motion.span>
        </motion.a>

        {/* Expandable Tabs - Desktop */}
        <nav className="hidden lg:flex items-center gap-2">
          {navItems.map((item) => (
            <motion.div
              key={item.href}
              className="relative cursor-pointer overflow-hidden rounded-full"
              variants={itemVariants}
              animate={expandedItem === item.href ? "expanded" : "collapsed"}
              onHoverStart={() => setExpandedItem(item.href)}
              onHoverEnd={() => setExpandedItem(null)}
              whileHover={{ scale: 1.02 }}
              transition={{ type: "spring", stiffness: 400, damping: 25 }}
            >
              <motion.a
                href={item.href}
                className="flex items-center px-3 py-3 relative"
                style={{
                  background: expandedItem === item.href ? "rgba(212,175,55,0.15)" : "transparent",
                  border: `1px solid ${expandedItem === item.href ? "rgba(212,175,55,0.4)" : "transparent"}`,
                  transition: "background 0.3s, border 0.3s",
                  boxShadow: expandedItem === item.href ? "0 0 20px rgba(212,175,55,0.15)" : "none",
                }}
              >
                <motion.div
                  animate={{
                    color: expandedItem === item.href ? "#d4af37" : "rgba(26,8,10,0.7)",
                    scale: expandedItem === item.href ? 1.1 : 1
                  }}
                  transition={{ duration: 0.2 }}
                >
                  <item.icon size={18} strokeWidth={1.5} />
                </motion.div>
                <motion.span
                  className="text-sm whitespace-nowrap font-medium"
                  variants={textVariants}
                  initial="hidden"
                  animate={expandedItem === item.href ? "visible" : "hidden"}
                  style={{ color: "#1a080a" }}
                >
                  {item.label}
                </motion.span>
              </motion.a>

              {/* Active indicator with glow */}
              <motion.div
                className="absolute bottom-1 left-1/2 h-0.5 rounded-full -translate-x-1/2"
                style={{
                  background: "linear-gradient(90deg, #d4af37, #f4d77a)",
                  boxShadow: "0 0 10px rgba(212,175,55,0.5)"
                }}
                initial={{ width: 0, opacity: 0 }}
                animate={{
                  width: expandedItem === item.href ? 24 : 0,
                  opacity: expandedItem === item.href ? 1 : 0
                }}
                transition={{ duration: 0.2 }}
              />
            </motion.div>
          ))}

          {/* Quote Button */}
          <motion.button
            onClick={onOpenQuote}
            className="ml-4"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.98 }}
          >
            <span
              className="flex items-center gap-2 px-5 py-3 rounded-full text-sm font-semibold"
              style={{
                background: "linear-gradient(135deg, #d4af37, #f4d77a)",
                color: "#1a080a",
                boxShadow: "0 4px 16px rgba(212,175,55,0.3)"
              }}
            >
              <motion.span
                animate={{ rotate: [0, -10, 10, 0] }}
                transition={{ duration: 0.5, repeat: Infinity, repeatDelay: 3 }}
              >
                <Sparkles size={16} />
              </motion.span>
              <span>Get Quote</span>
            </span>
          </motion.button>
        </nav>

        {/* Mobile Menu Button */}
        <motion.button
          className="lg:hidden text-[#1a080a] relative z-50"
          onClick={() => setOpen((s) => !s)}
          whileTap={{ scale: 0.9 }}
        >
          <AnimatePresence mode="wait">
            {open ? (
              <motion.div
                key="close"
                initial={{ rotate: -90, opacity: 0 }}
                animate={{ rotate: 0, opacity: 1 }}
                exit={{ rotate: 90, opacity: 0 }}
                transition={{ duration: 0.2 }}
              >
                <X size={24} />
              </motion.div>
            ) : (
              <motion.div
                key="menu"
                initial={{ rotate: 90, opacity: 0 }}
                animate={{ rotate: 0, opacity: 1 }}
                exit={{ rotate: -90, opacity: 0 }}
                transition={{ duration: 0.2 }}
              >
                <Menu size={24} />
              </motion.div>
            )}
          </AnimatePresence>
        </motion.button>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {open && (
          <motion.div
            className="lg:hidden mx-6 mt-3 p-6 rounded-2xl"
            style={{
              background: "rgba(253, 248, 237, 0.98)",
              backdropFilter: "blur(20px)",
              WebkitBackdropFilter: "blur(20px)",
              border: "1px solid rgba(212,175,55,0.3)",
              boxShadow: "0 8px 32px rgba(212,175,55,0.2)"
            }}
            variants={mobileMenuVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
          >
            <div className="flex flex-col gap-4">
              {navItems.map((item, i) => (
                <motion.a
                  key={item.href}
                  href={item.href}
                  onClick={() => setOpen(false)}
                  className="flex items-center gap-3 serif text-xl relative"
                  style={{ color: "#1a080a" }}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: -20 }}
                  transition={{ delay: i * 0.08, duration: 0.3 }}
                  whileHover={{ x: 10, color: "#d4af37" }}
                >
                  {/* Hover underline effect */}
                  <motion.div
                    className="absolute bottom-0 left-0 h-0.5"
                    style={{ background: "linear-gradient(90deg, #d4af37, transparent)", width: "0%" }}
                    whileHover={{ width: "100%" }}
                    transition={{ duration: 0.3 }}
                  />
                  <item.icon size={22} strokeWidth={1.5} />
                  {item.label}
                </motion.a>
              ))}
              <motion.button
                onClick={() => { setOpen(false); onOpenQuote(); }}
                className="mt-4 self-start"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: 10 }}
                transition={{ delay: 0.4, duration: 0.3 }}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.98 }}
              >
                <span
                  className="flex items-center gap-2 px-6 py-3 rounded-full text-sm font-semibold"
                  style={{
                    background: "linear-gradient(135deg, #d4af37, #f4d77a)",
                    color: "#1a080a",
                    boxShadow: "0 4px 20px rgba(212,175,55,0.3)"
                  }}
                >
                  <Sparkles size={16} />
                  Get Quote
                </span>
              </motion.button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.header>
  );
}
